        // ---------- Save & Continue / Save & Close ----------
        $scope.VisionTabOrder = [1, 2, 3, 4, 5, 6, 7, 8, 9, 13, 14];

        // 'continue' | 'close' | null. Set by the header buttons, consumed by AfterSaveNavigate.
        $scope._saveIntent = null;

        $scope._saveRefreshPending = false;

        function GetVisionTemplateCategory() {
            return ($scope.cacheStorageItem.DefaultTemplateArray || []).find(function (item) {
                return item.CategoryId == 3;
            });
        }

        // Mirrors the ng-show gates on the left nav, one for one.
        $scope.IsTabVisible = function (tabId) {
            var cat = GetVisionTemplateCategory();
            switch (tabId) {
                case 1: return $scope.CheckDefaultTemplateSubCategory(11);
                case 2: return !!cat && $scope.CheckDefaultTemplateTab(cat, 'Refraction');
                case 3: return $scope.CheckDefaultTemplateSubCategory(16);
                case 4: return $scope.CheckDefaultTemplateSubCategory(60);
                case 5: return $scope.CheckDefaultTemplateSubCategory(61);
                case 6: return $scope.CheckDefaultTemplateSubCategory(74);
                case 7: return $scope.CheckDefaultTemplateSubCategory(75);
                case 8: return $scope.CheckDefaultTemplateSubCategory(87);   // Dilation Drops
                case 9: return !!cat && $scope.CheckDefaultTemplateTab(cat, 'MiscTest');
                case 13: return $scope.CheckDefaultTemplateSubCategory(22);
                case 14: return $scope.CheckDefaultTemplateSubCategory(78);
                default: return false;
            }
        };

        $scope.GetNextVisibleTab = function (currentTab) {
            var idx = $scope.VisionTabOrder.indexOf(currentTab);
            if (idx === -1) return null;
            for (var i = idx + 1; i < $scope.VisionTabOrder.length; i++) {
                if ($scope.IsTabVisible($scope.VisionTabOrder[i])) {
                    return $scope.VisionTabOrder[i];
                }
            }
            return null;
        };

        // Refraction sub-tabs in header order. name drives the view (ng-if on refractionTab),
        $scope.RefractionSubTabs = [
            { "name": "autoRefraction", "subtab": 1, "gate": 49 },
            { "name": "retinoscopy", "subtab": 2, "gate": 36 },
            { "name": "currentGlassRx", "subtab": 3, "gate": 42 },
            { "name": "manifestRefraction", "subtab": 4, "gate": 50 },
            { "name": "cycloplegicRefraction", "subtab": 5, "gate": 54 },
            { "name": "overRefraction", "subtab": 6, "gate": 52 },
            { "name": "finalGlassRx", "subtab": 7, "gate": 57 }
        ];

        // Pure lookup: the next visible sub-tab within the current screen, or null when the
        // active sub-tab is the last one (or the screen has no sub-tabs).
        function GetNextVisibleSubTab() {
            if ($scope.tab !== 2) return null;
            var list = $scope.RefractionSubTabs;
            var idx = -1, i;
            for (i = 0; i < list.length; i++) {
                if (list[i].name === $scope.refractionTab) { idx = i; break; }
            }
            for (i = idx + 1; i < list.length; i++) {
                if ($scope.CheckDefaultTemplateSubCategory(list[i].gate)) return list[i];
            }
            return null;
        }

        // Advance within the current screen. Returns true when it moved.
        function GoToNextSubTab() {
            var next = GetNextVisibleSubTab();
            if (!next) return false;
            // Safe to reuse the normal click handler: the staged objects were cleared after
            // the save, so its push guards all see empty objects and push nothing.
            $scope.changeRefractionTab(next.name);
            $scope.subtab = next.subtab;
            return true;
        }

        // Last step overall: nothing left within this screen and no next screen.
        $scope.IsLastVisibleTab = function () {
            return GetNextVisibleSubTab() === null && $scope.GetNextVisibleTab($scope.tab) === null;
        };

