        function generateVisionLogs(newVisionList, oldVisionList, MasterTestUsedList) {
            MasterTestUsedList = MasterTestUsedList || [];
            let oldDescArr = [];
            let newDescArr = [];
            let dltDescArr = [];
            let dltcount = 0;

            function val(v) { return v ? v : ''; }

            function getTestName(tid) {
                const litem = (MasterTestUsedList || []).find(t => t.TestUserId == tid);
                return litem ? litem.TestName : tid || '';
            }

            function buildEyeString(item, type) {
                const eyes = [
                    { key: "RightEyeValues", label: "OD" },
                    { key: "LeftEyeValues", label: "OS" },
                    { key: "BothEyeValues", label: "OU" }
                ];
                let result = [];
                eyes.forEach(e => {
                    let v = val(item?.[e.key]?.[type]);
                    if (v) result.push(`${e.label}-${v}`);
                });
                return result.join(', ');
            }

            function buildSpecialFields(item) {
                let text = '';
                let id = item.InvestigationId;

                if (id == 2076 || id == 13) {
                    let remarksArr = [];
                    if (item.RightEyeValues?.Remarks)
                        remarksArr.push(`OD: ${item.RightEyeValues.Remarks}`);
                    if (item.LeftEyeValues?.Remarks)
                        remarksArr.push(`OS: ${item.LeftEyeValues.Remarks}`);
                    text = remarksArr.join(', ');
                } else if (id == 12) {
                    let parts = [];
                    if (item.Value == "1") parts.push("OD");
                    else if (item.Value == "2") parts.push("OS");
                    if (item.Remarks) parts.push("Notes :" + item.Remarks);
                    text = parts.join(', ');
                } else if (id == 2154) {
                    text =
                        `${item.Value ? `, Distance : ${getTestName(item.Value)}` : ''}` +
                        `${item.Lvalue ? `, Near : ${getTestName(item.Lvalue)}` : ''}`;
                }
                return text.trim().replace(/^, /, '');
            }

            //  Identify deleted items
            let deletedItems = [];
            let newItems = newVisionList.filter(x => x.ActiveInd === 'N');
            if (newItems.length > 0) {
                angular.forEach(newItems, function (item) {
                    let oldMatched = oldVisionList.find(
                        o => o.InvestigationId === item.InvestigationId
                    );

                    if (oldMatched) {
                        deletedItems.push(oldMatched);
                    }
                });
            }

            deletedItems.forEach(delItem => {
                dltcount++;
                let testName = '';

                if (delItem.InvestigationId == 5) {
                    testName = "CC(GL)";

                } else if (delItem.InvestigationId == 12) {
                    testName = "Ocular Dominance For";
                }
                else if (delItem.InvestigationId == 13) {
                    testName = "Pinhole-(D)";
                } else if (delItem.InvestigationId == 2076) {
                    testName = "TAC-(D)";
                } else {
                    testName = delItem.InvestigationDesc || '';
                }

                let dist = buildEyeString(delItem, "Distance");
                let near = buildEyeString(delItem, "Near");
                let special = buildSpecialFields(delItem);
                let parts = [];
                if (dist) parts.push(`${testName}-(D): ${dist}`);
                if (near) parts.push(`${testName}-(N): ${near}`);
                if (special) parts.push(`${testName}: ${special}`);
                dltDescArr.push(parts.join(' | '));
            });

            //   (Add/Edit)
            newVisionList.filter(x => x.ActiveInd !== 'N').forEach(newItem => {
                var testName = "";
                if (newItem.InvestigationId == 5) {
                    testName = "CC(GL)";

                } else if (newItem.InvestigationId == 12) {
                    testName = "Ocular Dominance For";
                }
                else if (newItem.InvestigationId == 13) {
                    testName = "Pinhole-(D)";
                } else if (newItem.InvestigationId == 2076) {
                    testName = "TAC-(D)";
                } else {
                    testName = newItem.InvestigationDesc || '';
                }
                // Check if same investigation was deleted earlier (delete + add combo)
                const DeletedEarlier = deletedItems.some(d => d.InvestigationId === newItem.InvestigationId);

                if (DeletedEarlier) {
                    // Get deleted version
                    const delItem = deletedItems.find(d => d.InvestigationId === newItem.InvestigationId);

                    let oldParts = [];
                    let newParts = [];

                    let delDist = buildEyeString(delItem, "Distance");
                    let delNear = buildEyeString(delItem, "Near");
                    let delSpecial = buildSpecialFields(delItem);

                    if (delDist) oldParts.push(`${testName}-(D): ${delDist}`);
                    if (delNear) oldParts.push(`${testName}-(N): ${delNear}`);
                    if (delSpecial) oldParts.push(`${testName}: ${delSpecial}`);

                    let newDist = buildEyeString(newItem, "Distance");
                    let newNear = buildEyeString(newItem, "Near");
                    let newSpecial = buildSpecialFields(newItem);

                    if (newDist) newParts.push(`${testName}-(D): ${newDist}`);
                    if (newNear) newParts.push(`${testName}-(N): ${newNear}`);
                    if (newSpecial) newParts.push(`${testName}: ${newSpecial}`);

                    // Remove duplicate oldDesc if already added for this item
                    oldDescArr = oldDescArr.filter(desc => !desc.includes(testName));

                    oldDescArr.push(oldParts.join(' | '));
                    newDescArr.push(newParts.join(' | '));
                } else {
                    // Normal compare (edit)
                    const oldItem = oldVisionList.find(o => o.InvestigationId === newItem.InvestigationId && o.ActiveInd !== 'N');

                    let oldParts = [];
                    let newParts = [];

                    let oldDist = buildEyeString(oldItem, "Distance");
                    let oldNear = buildEyeString(oldItem, "Near");
                    let oldSpecial = buildSpecialFields(oldItem || {});
                    let newDist = buildEyeString(newItem, "Distance");
                    let newNear = buildEyeString(newItem, "Near");
                    let newSpecial = buildSpecialFields(newItem);

                    if (oldDist) oldParts.push(`${testName}-(D): ${oldDist}`);
                    if (oldNear) oldParts.push(`${testName}-(N): ${oldNear}`);
                    if (oldSpecial) oldParts.push(`${testName}: ${oldSpecial}`);
                    if (newDist) newParts.push(`${testName}-(D): ${newDist}`);
                    if (newNear) newParts.push(`${testName}-(N): ${newNear}`);
                    if (newSpecial) newParts.push(`${testName}: ${newSpecial}`);

                    if (newParts.join(' | ') !== oldParts.join(' | ')) {
                        if (oldParts.length > 0) oldDescArr.push(oldParts.join(' | '));
                        newDescArr.push(newParts.join(' | '));
                    }
                }
            });

            const result = {
                oldDescription: oldDescArr.join(' | '),
                newDescription: newDescArr.join(' | '),

            };

            if (dltcount !== 0) {
                $scope.LogObj.LogArray.push({
                    LogId: 0,
                    ModuleId: 1,
                    ModuleName: "OUTPatient",
                    SubModuleId: 50,
                    SubModuleName: "Vision and Perception",
                    ScreenType: "V&P(Visual Acuity)",
                    ActionType: "Deleted",
                    OldActionDescription: dltDescArr.join("\n"),
                    NewActionDescription: "",
                    ActionDateTime: $filter("date")(new Date(), "yyyy-MM-dd HH:mm:ss")
                });
            }

            return result;
        }
        $scope.compareAutoRefraction = function () {
            const newList = $scope.VisionObj.ARDetails || [];
            const oldList = $scope.LogObj.AutoRefractionDetails || [];

            let oldDescArr = [];
            let newDescArr = [];
            let dltDescArr = [];
            let deletedCount = 0;
            let reAdded = false;

            function formatAR(item, index) {
                if (!item) return '';
                const right = item.RightEyeValues || {};
                const left = item.LeftEyeValues || {};

                let desc = `AR${index + 1}: `;
                let odParts = [];
                if (right.Spherical) odParts.push(right.Spherical);
                if (right.Cylindrical) odParts.push(right.Cylindrical);
                let odText = odParts.join('/');
                if (right.Axis) odText += `*${right.Axis}`;

                desc += `OD- ${odText || ''}`;
                // desc += `OD- ${right.Spherical || ''}/${right.Cylindrical || ''}*${right.Axis || ''}`;
                let osParts = [];
                if (left.Spherical) osParts.push(left.Spherical);
                if (left.Cylindrical) osParts.push(left.Cylindrical);
                let osText = osParts.join('/');
                if (left.Axis) osText += `*${left.Axis}`;

                desc += ` , OS- ${osText || ''}`;
                // desc += ` , OS- ${left.Spherical || ''}/${left.Cylindrical || ''}*${left.Axis || ''}`;
                if (item.Remarks && item.Remarks.trim() !== '') {
                    desc += ` , Remarks: ${item.Remarks.trim()}`;
                }
                if (item.GivenByName && item.GivenByName.trim() !== '') desc += ` , Added By: ${item.GivenByName}`;
                if (item.CreatedDateTime) desc += ` ${$filter('date')(item.CreatedDateTime, "MM-dd-yyyy hh:mm a")}`;

                return desc;
            }

            //  Detect deleted items
            oldList.forEach((oldItem, idx) => {
                const exists = newList.find(n => n.PatientFindingAutoRefractionId === oldItem.PatientFindingAutoRefractionId);
                if (!exists || exists.DeleteInd === 'Y') {
                    dltDescArr.push(formatAR(oldItem, idx));
                    deletedCount++;
                }
            });

            //  Detect new or changed items
            newList.forEach((newItem, idx) => {
                if (newItem.DeleteInd === 'Y') return;

                const oldItem = oldList.find(o => o.PatientFindingAutoRefractionId === newItem.PatientFindingAutoRefractionId);
                if (!oldItem) {
                    newDescArr.push(formatAR(newItem, idx));
                    if (deletedCount > 0) reAdded = true;
                } else {
                    const oldStr = JSON.stringify({
                        R: oldItem.RightEyeValues, L: oldItem.LeftEyeValues, Remarks: oldItem.Remarks || ''
                    });
                    const newStr = JSON.stringify({
                        R: newItem.RightEyeValues, L: newItem.LeftEyeValues, Remarks: newItem.Remarks || ''
                    });
                    if (oldStr !== newStr) {
                        oldDescArr.push(formatAR(oldItem, idx));
                        newDescArr.push(formatAR(newItem, idx));
                    }
                }
            });

            const result = {
                oldDescription: oldDescArr.join('\n').trim(),
                newDescription: newDescArr.join('\n').trim(),

            };


            if (deletedCount > 0) {
                const logObj = {
                    LogId: 0,
                    ModuleId: 1,
                    ModuleName: "OUTPatient",
                    SubModuleId: 50,
                    SubModuleName: "Vision and Perception",
                    ScreenType: "Auto Refraction",
                    ActionType: "Deleted",
                    OldActionDescription: dltDescArr.join('\n').trim(),
                    NewActionDescription: "",
                    ActionDateTime: $filter("date")(new Date(), "yyyy-MM-dd HH:mm:ss")
                };
                $scope.LogObj.LogArray.push(logObj);
            }
            return result;
        };

