        function IOPAvgBetweenValues(value) {
            if (440 <= parseFloat(value) && parseFloat(value) <= 445) {
                return 7;
            } else if (446 <= parseFloat(value) && parseFloat(value) <= 455) {
                return 6;
            } else if (456 <= parseFloat(value) && parseFloat(value) <= 465) {
                return 6;
            } else if (467 <= parseFloat(value) && parseFloat(value) <= 475) {
                return 5;
            } else if (476 <= parseFloat(value) && parseFloat(value) <= 485) {
                return 4;
            } else if (486 <= parseFloat(value) && parseFloat(value) <= 495) {
                return 4;
            } else if (496 <= parseFloat(value) && parseFloat(value) <= 505) {
                return 3;
            } else if (506 <= parseFloat(value) && parseFloat(value) <= 515) {
                return 2;
            } else if (516 <= parseFloat(value) && parseFloat(value) <= 525) {
                return 1;
            } else if (526 <= parseFloat(value) && parseFloat(value) <= 535) {
                return 1;
            } else if (536 <= parseFloat(value) && parseFloat(value) <= 545) {
                return 0;
            } else if (546 <= parseFloat(value) && parseFloat(value) <= 555) {
                return -1;
            } else if (556 <= parseFloat(value) && parseFloat(value) <= 565) {
                return -1;
            } else if (566 <= parseFloat(value) && parseFloat(value) <= 575) {
                return -2;
            } else if (576 <= parseFloat(value) && parseFloat(value) <= 585) {
                return -3;
            } else if (586 <= parseFloat(value) && parseFloat(value) <= 595) {
                return -4;
            } else if (596 <= parseFloat(value) && parseFloat(value) <= 605) {
                return -4;
            } else if (606 <= parseFloat(value) && parseFloat(value) <= 615) {
                return -5;
            } else if (616 <= parseFloat(value) && parseFloat(value) <= 625) {
                return -6;
            } else if (626 <= parseFloat(value) && parseFloat(value) <= 635) {
                return -6;
            } else if (parseFloat(value) >= 636) {
                return -7;
            }
            //else if (636 <= parseFloat(value) && parseFloat(value) <= 645) {
            //    return -7;
            //} else {
            //    return null;
            //}
        }
        function IOPCCValues() {
            var PachyArray = $filter("filter")($scope.VisionObj.PachymetryArray.Pachymetry, { "ActiveInd": 'Y' }, true);
            angular.forEach($scope.VisionObj.TonoMetryDetailsArray.IOPArray, function (Iitem) {
                if (PachyArray.length > 0) {
                    if (Iitem.ActiveInd == "Y") {
                        if (Iitem.DilationType == 'Before Dilation') {
                            Iitem.BeforeDilationODCC = parseFloat(Iitem.BeforeDilationRightEye) + $scope.tempODcc || "";
                            Iitem.BeforeDilationOSCC = parseFloat(Iitem.BeforeDilationLeftEye) + $scope.tempOScc || "";
                        } else {
                            Iitem.AfterDilationODCC = parseInt(Iitem.AfterDilationRightEye) + $scope.tempODcc || "";
                            Iitem.AfterDilationOSCC = parseInt(Iitem.AfterDilationLeftEye) + $scope.tempOScc || "";
                        }
                    }
                } else {
                    Iitem.BeforeDilationODCC = "";
                    Iitem.BeforeDilationOSCC = "";
                }
            });
        }
        function IOPandPachymetryAvgValues() {
            $scope.VisionObj.IOPodCC = null;
            $scope.VisionObj.IOPosCC = null;
            $scope.VisionObj.IOPAvgODValue = 0;
            $scope.VisionObj.IOPAvgOSValue = 0;
            var Count = 0;
            var ODAvgValue = 0;
            var OSAvgValue = 0;
            if ($scope.VisionObj.TonoMetryDetailsArray != undefined) {
                if ($scope.VisionObj.TonoMetryDetailsArray.IOPArray.length > 0) {
                    angular.forEach($scope.VisionObj.TonoMetryDetailsArray.IOPArray, function (Iitem) {
                        if (Iitem.ActiveInd == "Y") {
                            if (Iitem.DilationType == 'Before Dilation') {
                                ODAvgValue += parseInt(Iitem.BeforeDilationRightEye) || 0;
                                OSAvgValue += parseInt(Iitem.BeforeDilationLeftEye) || 0;
                            } else {
                                ODAvgValue += parseInt(Iitem.AfterDilationRightEye) || 0;
                                OSAvgValue += parseInt(Iitem.AfterDilationLeftEye) || 0;
                            }
                            Count++;
                        }
                    });
                    $scope.VisionObj.IOPAvgODValue = parseFloat(ODAvgValue / Count).toFixed(1) || 0;
                    $scope.VisionObj.IOPAvgOSValue = parseFloat(OSAvgValue / Count).toFixed(1) || 0;
                }
            }
            $scope.VisionObj.PachymetryAvgODValue = 0;
            $scope.VisionObj.PachymetryAvgOSValue = 0;
            var count1 = 0;
            var count2 = 0;
            var pachyODAvgValue = 0;
            var pachyOSAvgValue = 0;
            var ODCCvalue = null;
            var OSCCvalue = null;
            if ($scope.VisionObj.PachymetryArray != undefined) {
                $scope.VisionObj.PachymetryArray.Pachymetry = $scope.VisionObj.PachymetryArray.Pachymetry || [];
                if ($scope.VisionObj.PachymetryArray.Pachymetry.length > 0) {
                    angular.forEach($scope.VisionObj.PachymetryArray.Pachymetry, function (pitem) {
                        if (pitem.ActiveInd == "Y") {
                            if (pitem.RightEye != '') {
                                pachyODAvgValue += parseInt(pitem.RightEye) || 0;
                                count1++;
                            }
                            if (pitem.LeftEye != '') {
                                pachyOSAvgValue += parseInt(pitem.LeftEye) || 0;
                                count2++;
                            }

                        }
                    });
                    if (pachyODAvgValue != 0) {
                        $scope.VisionObj.PachymetryAvgODValue = parseFloat(pachyODAvgValue / count1).toFixed(2) || 0;
                    }
                    if ($scope.VisionObj.PachymetryAvgODValue != 0) {
                        ODCCvalue = IOPAvgBetweenValues(Math.round($scope.VisionObj.PachymetryAvgODValue));
                        $scope.tempODcc = angular.copy(ODCCvalue);
                    }
                    if (pachyOSAvgValue != 0) {
                        $scope.VisionObj.PachymetryAvgOSValue = parseFloat(pachyOSAvgValue / count2).toFixed(2) || 0;
                    }
                    if ($scope.VisionObj.PachymetryAvgOSValue != 0) {
                        OSCCvalue = IOPAvgBetweenValues(Math.round($scope.VisionObj.PachymetryAvgOSValue));
                        $scope.tempOScc = angular.copy(OSCCvalue);
                    }
                }
            }

            if (ODCCvalue != null && parseFloat($scope.VisionObj.IOPAvgODValue) != 0) {
                $scope.VisionObj.IOPodCC = parseFloat($scope.VisionObj.IOPAvgODValue) + ODCCvalue || null;
            } else {
                $scope.VisionObj.IOPodCC = null;
            }
            if (OSCCvalue != null && parseFloat($scope.VisionObj.IOPAvgOSValue) != 0) {
                $scope.VisionObj.IOPosCC = parseFloat($scope.VisionObj.IOPAvgOSValue) + OSCCvalue || null;
            } else {
                $scope.VisionObj.IOPosCC = null;
            }

            //add function for EachIopCC values()
            IOPCCValues();

        }




