        function GetKeratometryAxisValues() {
            var r = 0;
            var array = [];
            while (r <= 180) {
                var obj = {
                    "Id": r, "Value": r.toString(), "selected": false
                };
                array.push(obj);
                r++;
            }
            return array;
        }
        function GetIOPValues() {
            //var r = 1;
            var r = 0;
            var array = [];
            while (r <= 80) {
                var obj = {
                    "Id": r, "Value": r.toString(), "selected": false
                };
                array.push(obj);
                r++;
            }
            return array;
        }
