        $scope.CopyVisualActiveValues = function () {
            if ($scope.VisionObj.VisionDetails.length > 0) {
                angular.forEach($scope.VisionObj.VisionDetails, function (item) {
                    if (item.InvestigationId === 4 || item.InvestigationId === 5 || item.InvestigationId === 12 || item.InvestigationId === 13 ||
                        item.InvestigationId === 2071 || item.InvestigationId === 2073 || item.InvestigationId === 2154 || item.InvestigationId === 2076) {

                        item.LeftEyeValues.Distance = item.RightEyeValues.Distance || "";
                        item.LeftEyeValues.Near = item.RightEyeValues.Near || "";
                        item.LeftEyeValues.Remarks = item.RightEyeValues.Remarks || "";
                        item.Lvalue = item.Rvalue || "";
                    }
                });
            }

            $scope.UnaidedDistanceListOS = angular.copy($scope.GetNewDistanceList());
            $scope.UnaidedNearListOS = angular.copy($scope.GetMeterNearList());
            $scope.AidedGlassDistanceListOS = angular.copy($scope.GetNewDistanceList());
            $scope.AidedGlassNearListOS = angular.copy($scope.GetMeterNearList());
            $scope.AidedContactDistanceListOS = angular.copy($scope.GetNewDistanceList());
            $scope.AidedContactNearListOS = angular.copy($scope.GetMeterNearList());
            $scope.TACListOS = angular.copy($scope.GetTACArrayType());
            $scope.TACListOS = $filter("filter")($scope.TACListOS, { "Type": "1" }, true);
            $scope.PinholeListOS = angular.copy($scope.GetPinholeList());


            if ($scope.VisionObj.VisionDetails.length > 0) {
                let tempSphArray = $filter('filter')($scope.VisionObj.VisionDetails, { 'InvestigationId': 4 },);
                if (tempSphArray.length > 0) {
                    let tempPrismVtArray = $filter('filter')($scope.UnaidedDistanceListOS, { "Value": VaBaseValue(tempSphArray[0].RightEyeValues, 'Distance') }, true);
                    if (tempPrismVtArray.length > 0) {
                        let tempPrismVtObj = tempPrismVtArray[0];
                        let PrismVtIndex = $scope.UnaidedDistanceListOS.indexOf(tempPrismVtObj);
                        $scope.UnaidedDistanceListOS[PrismVtIndex].selected = true;
                    }
                    let tempNearArray = $filter('filter')($scope.UnaidedNearListOS, { "Value": VaBaseValue(tempSphArray[0].RightEyeValues, 'Near') }, true);
                    if (tempNearArray.length > 0) {
                        let tempNearVtObj = tempNearArray[0];
                        let PrismVtIndex = $scope.UnaidedNearListOS.indexOf(tempNearVtObj);
                        $scope.UnaidedNearListOS[PrismVtIndex].selected = true;
                    }
                }
                let tempGlassDArray = $filter('filter')($scope.VisionObj.VisionDetails, { 'InvestigationId': 5 },);
                if (tempGlassDArray.length > 0) {
                    let tempGlassVtArray = $filter('filter')($scope.AidedGlassDistanceListOS, { "Value": VaBaseValue(tempGlassDArray[0].RightEyeValues, 'Distance') }, true);
                    if (tempGlassVtArray.length > 0) {
                        let tempGlassVtObj = tempGlassVtArray[0];
                        let PrismVtIndex = $scope.AidedGlassDistanceListOS.indexOf(tempGlassVtObj);
                        $scope.AidedGlassDistanceListOS[PrismVtIndex].selected = true;
                    }
                    let tempNearCcArray = $filter('filter')($scope.AidedGlassNearListOS, { "Value": VaBaseValue(tempGlassDArray[0].RightEyeValues, 'Near') }, true);
                    if (tempNearCcArray.length > 0) {
                        let tempNearVtObj = tempNearCcArray[0];
                        let PrismVtIndex = $scope.AidedGlassNearListOS.indexOf(tempNearVtObj);
                        $scope.AidedGlassNearListOS[PrismVtIndex].selected = true;
                    }
                }
                let tempGlassCArray1 = $filter('filter')($scope.VisionObj.VisionDetails, { 'InvestigationId': 2071 },);
                if (tempGlassCArray1.length > 0) {
                    let tempGlassCArray = $filter('filter')($scope.AidedContactDistanceListOS, { "Value": VaBaseValue(tempGlassCArray1[0].RightEyeValues, 'Distance') }, true);
                    if (tempGlassCArray.length > 0) {
                        let tempGlassVtObj = tempGlassCArray[0];
                        let PrismVtIndex = $scope.AidedContactDistanceListOS.indexOf(tempGlassVtObj);
                        $scope.AidedContactDistanceListOS[PrismVtIndex].selected = true;
                    }
                    let tempNearCArray = $filter('filter')($scope.AidedContactNearListOS, { "Value": VaBaseValue(tempGlassCArray1[0].RightEyeValues, 'Near') }, true);
                    if (tempNearCArray.length > 0) {
                        let tempNearVtObj = tempNearCArray[0];
                        let PrismVtIndex = $scope.AidedContactNearListOS.indexOf(tempNearVtObj);
                        $scope.AidedContactNearListOS[PrismVtIndex].selected = true;
                    }
                }
                let tempGlassCpArray = $filter('filter')($scope.VisionObj.VisionDetails, { 'InvestigationId': 13 },);
                if (tempGlassCpArray.length > 0) {
                    let tempGlassCHArray = $filter('filter')($scope.PinholeListOS, { "Value": VaBaseValue(tempGlassCpArray[0].RightEyeValues, 'Remarks') }, true);
                    if (tempGlassCHArray.length > 0) {
                        let tempGlassVtObj = tempGlassCHArray[0];
                        let PrismVtIndex = $scope.PinholeListOS.indexOf(tempGlassVtObj);
                        $scope.PinholeListOS[PrismVtIndex].selected = true;
                    }
                }
                let tempGlassCTACArray = $filter('filter')($scope.VisionObj.VisionDetails, { 'InvestigationId': 2076 },);
                if (tempGlassCTACArray.length > 0) {
                    let tempGlassTACArray = $filter('filter')($scope.TACList, { "Value": VaBaseValue(tempGlassCTACArray[0].RightEyeValues, 'Remarks') }, true);
                    if (tempGlassTACArray.length > 0) {
                        let tempGlassVtObj1 = tempGlassTACArray[0];
                        let tacIndex = $scope.TACList.indexOf(tempGlassVtObj1);
                        if (tempGlassTACArray[0].Type == '1') {
                            $scope.TACListOS[tacIndex].selected = true;
                        }
                        if (tempGlassTACArray[0].Type == '2') {
                            $scope.TACListOS[tacIndex].selected = true;
                        }
                        if (tempGlassTACArray[0].Type == '3') {
                            $scope.TACListOS[tacIndex].selected = true;
                        }
                    }
                }
            }

        };
