        $scope.ChangeSelectAutoFillValues = function (EyeType, Type) {

            if (EyeType == "OD") {
                angular.forEach($scope.VisionObj.VisionDetails, function (mitem) {
                    if (mitem.InvestigationId == 4) {
                        angular.forEach($scope.UnaidedDistanceList, function (item) {
                            if (item.Value == VaBaseValue(mitem.RightEyeValues, 'Distance')) {
                                item.selected = true;
                            }
                        });
                        angular.forEach($scope.UnaidedNearList, function (item) {
                            if (item.Value == VaBaseValue(mitem.RightEyeValues, 'Near')) {
                                item.selected = true;
                            }
                        });
                        angular.forEach($scope.UnaidedDistanceListOS, function (item) {
                            if (item.Value == VaBaseValue(mitem.LeftEyeValues, 'Distance')) {
                                item.selected = true;
                            }
                        });
                        angular.forEach($scope.UnaidedNearListOS, function (item) {
                            if (item.Value == VaBaseValue(mitem.LeftEyeValues, 'Near')) {
                                item.selected = true;
                            }
                        });
                        angular.forEach($scope.UnaidedDistanceListOU, function (item) {
                            if (item.Value == VaBaseValue(mitem.BothEyeValues, 'Distance')) {
                                item.selected = true;
                            }
                        });
                        angular.forEach($scope.UnaidedNearListOU, function (item) {
                            if (item.Value == VaBaseValue(mitem.BothEyeValues, 'Near')) {
                                item.selected = true;
                            }
                        });
                    }
                    else if (mitem.InvestigationId == 5) {
                        angular.forEach($scope.AidedGlassDistanceList, function (item) {
                            if (item.Value == VaBaseValue(mitem.RightEyeValues, 'Distance')) {
                                item.selected = true;
                            }
                        });
                        angular.forEach($scope.AidedGlassNearList, function (item) {
                            if (item.Value == VaBaseValue(mitem.RightEyeValues, 'Near')) {
                                item.selected = true;
                            }
                        });
                        angular.forEach($scope.AidedGlassDistanceListOS, function (item) {
                            if (item.Value == VaBaseValue(mitem.LeftEyeValues, 'Distance')) {
                                item.selected = true;
                            }
                        });
                        angular.forEach($scope.AidedGlassNearListOS, function (item) {
                            if (item.Value == VaBaseValue(mitem.LeftEyeValues, 'Near')) {
                                item.selected = true;
                            }
                        });
                        angular.forEach($scope.AidedGlassDistanceListOU, function (item) {
                            if (item.Value == VaBaseValue(mitem.BothEyeValues, 'Distance')) {
                                item.selected = true;
                            }
                        });
                        angular.forEach($scope.AidedGlassNearListOU, function (item) {
                            if (item.Value == VaBaseValue(mitem.BothEyeValues, 'Near')) {
                                item.selected = true;
                            }
                        });
                    }
                    else if (mitem.InvestigationId == 2071) {
                        angular.forEach($scope.AidedContactDistanceList, function (item) {
                            if (item.Value == VaBaseValue(mitem.RightEyeValues, 'Distance')) {
                                item.selected = true;
                            }
                        });
                        angular.forEach($scope.AidedContactNearList, function (item) {
                            if (item.Value == VaBaseValue(mitem.RightEyeValues, 'Near')) {
                                item.selected = true;
                            }
                        });
                        angular.forEach($scope.AidedContactDistanceListOS, function (item) {
                            if (item.Value == VaBaseValue(mitem.LeftEyeValues, 'Distance')) {
                                item.selected = true;
                            }
                        });
                        angular.forEach($scope.AidedContactNearListOS, function (item) {
                            if (item.Value == VaBaseValue(mitem.LeftEyeValues, 'Near')) {
                                item.selected = true;
                            }
                        });
                        angular.forEach($scope.AidedContactDistanceListOU, function (item) {
                            if (item.Value == VaBaseValue(mitem.BothEyeValues, 'Distance')) {
                                item.selected = true;
                            }
                        });
                        angular.forEach($scope.AidedContactNearListOU, function (item) {
                            if (item.Value == VaBaseValue(mitem.BothEyeValues, 'Near')) {
                                item.selected = true;
                            }
                        });
                    }
                    else if (mitem.InvestigationId == 2076) {
                        // TAC cm is per eye (Rvalue = OD, Lvalue = OS); filtering both
                        // lists by the shared mitem.Value put each eye on the wrong list.
                        $scope.SyncTACTypeFromValues(mitem);
                        $scope.ChangeTACInvestigation(mitem, 1);   // TACList   (OD)
                        $scope.ChangeTACInvestigation(mitem, 2);   // TACListOS (OS)
                    }
                    else if (mitem.InvestigationId == 13) {
                        angular.forEach($scope.PinholeList, function (item) {
                            if (item.Value == VaBaseValue(mitem.RightEyeValues, 'Remarks')) {
                                item.selected = true;
                            }
                        });
                        angular.forEach($scope.PinholeListOS, function (item) {
                            if (item.Value == VaBaseValue(mitem.LeftEyeValues, 'Remarks')) {
                                item.selected = true;
                            }
                        });
                    }
                });
            } else if (EyeType == "OS") {
                angular.forEach($scope.VisionObj.VisionDetails, function (mitem) {
                    if (mitem.InvestigationId == 4) {
                        angular.forEach($scope.UnaidedDistanceList, function (item) {
                            if (item.Value == VaBaseValue(mitem.LeftEyeValues, 'Distance')) {
                                item.selected = true;
                            }
                        });
                        angular.forEach($scope.UnaidedNearList, function (item) {
                            if (item.Value == VaBaseValue(mitem.LeftEyeValues, 'Near')) {
                                item.selected = true;
                            }
                        });
                    }
                    else if (mitem.InvestigationId == 5) {
                        angular.forEach($scope.AidedGlassDistanceList, function (item) {
                            if (item.Value == VaBaseValue(mitem.LeftEyeValues, 'Distance')) {
                                item.selected = true;
                            }
                        });
                        angular.forEach($scope.AidedGlassNearList, function (item) {
                            if (item.Value == VaBaseValue(mitem.LeftEyeValues, 'Near')) {
                                item.selected = true;
                            }
                        });
                    }
                    else if (mitem.InvestigationId == 2071) {
                        angular.forEach($scope.AidedContactDistanceList, function (item) {
                            if (item.Value == VaBaseValue(mitem.LeftEyeValues, 'Distance')) {
                                item.selected = true;
                            }
                        });
                        angular.forEach($scope.AidedContactNearList, function (item) {
                            if (item.Value == VaBaseValue(mitem.LeftEyeValues, 'Near')) {
                                item.selected = true;
                            }
                        });
                    }
                    else if (mitem.InvestigationId == 2076) {
                        // this OS branch was marking the OS value inside TACList (the OD
                        // list) and never building TACListOS, which the OS chips render
                        $scope.SyncTACTypeFromValues(mitem);
                        $scope.ChangeTACInvestigation(mitem, 1);   // TACList   (OD)
                        $scope.ChangeTACInvestigation(mitem, 2);   // TACListOS (OS)
                    }
                    else if (mitem.InvestigationId == 13) {
                        angular.forEach($scope.PinholeList, function (item) {
                            if (item.Value == VaBaseValue(mitem.LeftEyeValues, 'Remarks')) {
                                item.selected = true;
                            }
                        });
                    }
                });
            } else if (EyeType == "OU") {
                angular.forEach($scope.VisionObj.VisionDetails, function (mitem) {
                    if (mitem.InvestigationId == 4) {
                        angular.forEach($scope.UnaidedDistanceList, function (item) {
                            if (item.Value == VaBaseValue(mitem.BothEyeValues, 'Distance')) {
                                item.selected = true;
                            }
                        });
                        angular.forEach($scope.UnaidedNearList, function (item) {
                            if (item.Value == VaBaseValue(mitem.BothEyeValues, 'Near')) {
                                item.selected = true;
                            }
                        });
                    }
                    else if (mitem.InvestigationId == 5) {
                        angular.forEach($scope.AidedGlassDistanceList, function (item) {
                            if (item.Value == VaBaseValue(mitem.BothEyeValues, 'Distance')) {
                                item.selected = true;
                            }
                        });
                        angular.forEach($scope.AidedGlassNearList, function (item) {
                            if (item.Value == VaBaseValue(mitem.BothEyeValues, 'Near')) {
                                item.selected = true;
                            }
                        });
                    }
                    else if (mitem.InvestigationId == 2071) {
                        angular.forEach($scope.AidedContactDistanceList, function (item) {
                            if (item.Value == VaBaseValue(mitem.BothEyeValues, 'Distance')) {
                                item.selected = true;
                            }
                        });
                        angular.forEach($scope.AidedContactNearList, function (item) {
                            if (item.Value == VaBaseValue(mitem.BothEyeValues, 'Near')) {
                                item.selected = true;
                            }
                        });
                    }
                });
            }
        }
        $scope.ChangeTestedUser = function (item) {
            if (item.Value == null) {
                item.Value = "";
            }
        }
        $scope.ChangeSelectPamAutoFillValues = function (EyeType, Type) {
            angular.forEach($scope.VisionObj.VisionDetails, function (mitem) {
                if (mitem.InvestigationId == 2155 && mitem.ActiveInd == 'Y') {
                    angular.forEach($scope.PAMODList, function (item) {
                        if (item.Value == mitem.RightEye) {
                            item.selected = true;
                        }
                    });
                    angular.forEach($scope.PAMOSList, function (item) {
                        if (item.Value == mitem.LeftEye) {
                            item.selected = true;
                        }
                    });
                }
            });
        }

