        $scope.KeratometercalculateRightAvgKValue = function (item) {
            var avgval = "";
            var cylVal = "";
            if ((item.RHorizontalAxis !== "" && item.RHorizontalAxis !== undefined) || (item.RVerticalAxis !== "" && item.RVerticalAxis !== undefined)) {
                var calVal = parseFloat(item.RHorizontalAxis ? item.RHorizontalAxis : 0) + parseFloat(item.RVerticalAxis ? item.RVerticalAxis : 0);
                avgval = calVal / 2;

                cylVal = parseFloat(item.RHorizontalAxis ? item.RHorizontalAxis : 0) - parseFloat(item.RVerticalAxis ? item.RVerticalAxis : 0);


                item.RAverageKeretometerValue = avgval;
                if (cylVal < 0) {
                    item.RCylindricalValue = -(cylVal);
                }
                else {
                    item.RCylindricalValue = cylVal;
                }
            }
            else {
                item.RAverageKeretometerValue = avgval;
                item.RCylindricalValue = cylVal;
            }
        };
        $scope.KeratometercalculateRighthorizontalValues = function (item) {
            var VerticalVal = "";
            var CalcValue = 90;
            if (item.RHorizontalNewAxis !== "" && item.RHorizontalNewAxis !== undefined) {
                var Keretometervalue = parseInt(item.RHorizontalNewAxis);
                if (Keretometervalue <= 90) {
                    VerticalVal = (Keretometervalue) + CalcValue;
                }
                if (Keretometervalue > 90) {
                    VerticalVal = -(CalcValue - Keretometervalue);
                }
                item.RVerticalNewAxis = VerticalVal;
            }
            else {
                item.RVerticalNewAxis = VerticalVal;
            }
        };
        $scope.KeratometercalculateRightVerticalValues = function (item) {
            var VerticalVal = "";
            var CalcValue = 90;
            if (item.RVerticalNewAxis !== "" && item.RVerticalNewAxis !== undefined) {
                var Keretometervalue = parseInt(item.RVerticalNewAxis);
                if (Keretometervalue <= 90) {
                    VerticalVal = (Keretometervalue) + CalcValue;
                }

                if (Keretometervalue > 90) {
                    VerticalVal = -(CalcValue - Keretometervalue);
                }
                item.RHorizontalNewAxis = VerticalVal;
            }
            else {
                item.RHorizontalNewAxis = VerticalVal;
            }
        };
        $scope.KeratometercalculateLeftAvgKValue = function (item) {
            var avgval = "";
            var cylVal = "";
            if ((item.LHorizontalAxis !== "" && item.LHorizontalAxis !== undefined) || (item.LVerticalAxis !== "" && item.LVerticalAxis !== undefined)) {
                var calVal = parseFloat(item.LHorizontalAxis ? item.LHorizontalAxis : 0) + parseFloat(item.LVerticalAxis ? item.LVerticalAxis : 0);
                avgval = calVal / 2;
                cylVal = parseFloat(item.LHorizontalAxis ? item.LHorizontalAxis : 0) - parseFloat(item.LVerticalAxis ? item.LVerticalAxis : 0);
                item.LAverageKeretometerValue = avgval;
                if (cylVal < 0) {
                    item.LCylindricalValue = -(cylVal);
                }
                else {
                    item.LCylindricalValue = cylVal;
                }
            }
            else {
                item.LAverageKeretometerValue = avgval;
                item.LCylindricalValue = cylVal;
            }
        };
        $scope.KeratometercalculatelefthorizontalValues = function (item, inv) {
            var VerticalVal = "";
            var CalcValue = 90;
            if (item.LHorizontalNewAxis !== "" && item.LHorizontalNewAxis !== undefined) {
                var Keretometervalue = parseInt(item.LHorizontalNewAxis);
                if (Keretometervalue <= 90) {
                    VerticalVal = (Keretometervalue) + CalcValue;
                }

                if (Keretometervalue > 90) {
                    VerticalVal = -(CalcValue - Keretometervalue);
                }
                item.LVerticalNewAxis = VerticalVal;
            }
            else {
                item.LVerticalNewAxis = VerticalVal;
            }
        };
        $scope.KeratometercalculateleftVerticalValues = function (item, inv) {
            var VerticalVal = "";
            var CalcValue = 90;
            if (item.LVerticalNewAxis !== "" && item.LVerticalNewAxis !== undefined) {
                var Keretometervalue = parseInt(item.LVerticalNewAxis);
                if (Keretometervalue <= 90) {
                    VerticalVal = (Keretometervalue) + CalcValue;
                }

                if (Keretometervalue > 90) {
                    VerticalVal = -(CalcValue - Keretometervalue);
                }
                item.LHorizontalNewAxis = VerticalVal;
            }
            else {
                item.LHorizontalNewAxis = VerticalVal;
            }
        };

