        $scope.ADDTonometeryobj = function (obj, type) {

            var Tonometry = angular.copy(obj);
            if (Tonometry.BeforeDilationRightEye == '' && Tonometry.BeforeDilationLeftEye == '' && Tonometry.AfterDilationRightEye == '' && Tonometry.AfterDilationLeftEye == '') {  // Tonometry.Remarks == ''
                if (type == "Final") { } else {
                    alertify.error("Please Enter Value");
                }
                return false;
            }
            if ($scope.VisionObj.TonoMetryDetailsArray != undefined) {
                //Tonometry.BeforeDilationRightEyeCC = parseInt(Tonometry.BeforeDilationRightEye) + 7 || "";
                //Tonometry.BeforeDilationLeftEyeCC = parseInt(Tonometry.BeforeDilationLeftEye) + 7 || "";
                //Tonometry.AfterDilationRightEyeCC = parseInt(Tonometry.AfterDilationRightEye) + 7 || "";
                //Tonometry.AfterDilationLeftEyeCC = parseInt(Tonometry.AfterDilationLeftEye) + 7 || "";

                Tonometry.ColorRightEyeValue = 0;
                Tonometry.Rcolorprogress = "black";
                Tonometry.ColorLeftEyeValue = 0;
                Tonometry.Lcolorprogress = "black";
                if (Tonometry.DilationType == 'Before Dilation') {
                    if (Tonometry.BeforeDilationRightEye != '') {
                        Tonometry.ColorRightEyeValue = Math.round(parseFloat(Tonometry.BeforeDilationRightEye).toFixed(1)) || 0;
                        Tonometry.Rcolorprogress = (Tonometry.ColorRightEyeValue >= 0 && Tonometry.ColorRightEyeValue <= 4) ? "red" : ((Tonometry.ColorRightEyeValue >= 10 && Tonometry.ColorRightEyeValue <= 18) ? "" : ((Tonometry.ColorRightEyeValue >= 19 && Tonometry.ColorRightEyeValue <= 21) ? "#e6b800" : ((Tonometry.ColorRightEyeValue >= 5 && Tonometry.ColorRightEyeValue <= 9) ? "#e6b800" : ((Tonometry.ColorRightEyeValue >= 22) ? "red" : "black"))));
                    }
                    if (Tonometry.BeforeDilationLeftEye != '') {
                        Tonometry.ColorLeftEyeValue = Math.round(parseFloat(Tonometry.BeforeDilationLeftEye).toFixed(1)) || 0;
                        Tonometry.Lcolorprogress = (Tonometry.ColorLeftEyeValue >= 0 && Tonometry.ColorLeftEyeValue <= 4) ? "red" : ((Tonometry.ColorLeftEyeValue >= 10 && Tonometry.ColorLeftEyeValue <= 18) ? "" : ((Tonometry.ColorLeftEyeValue >= 19 && Tonometry.ColorLeftEyeValue <= 21) ? "#e6b800" : ((Tonometry.ColorLeftEyeValue >= 5 && Tonometry.ColorLeftEyeValue <= 9) ? "#e6b800" : ((Tonometry.ColorLeftEyeValue >= 22) ? "red" : "black"))));
                    }
                } else {
                    if (Tonometry.AfterDilationRightEye != '') {
                        Tonometry.ColorRightEyeValue = Math.round(parseFloat(Tonometry.AfterDilationRightEye).toFixed(1)) || 0;
                        Tonometry.Rcolorprogress = (Tonometry.ColorRightEyeValue >= 0 && Tonometry.ColorRightEyeValue <= 4) ? "red" : ((Tonometry.ColorRightEyeValue >= 10 && Tonometry.ColorRightEyeValue <= 18) ? "" : ((Tonometry.ColorRightEyeValue >= 19 && Tonometry.ColorRightEyeValue <= 21) ? "#e6b800" : ((Tonometry.ColorRightEyeValue >= 5 && Tonometry.ColorRightEyeValue <= 9) ? "#e6b800" : ((Tonometry.ColorRightEyeValue >= 22) ? "red" : "black"))));
                    }
                    if (Tonometry.AfterDilationLeftEye != '') {
                        Tonometry.ColorLeftEyeValue = Math.round(parseFloat(Tonometry.AfterDilationLeftEye).toFixed(1)) || 0;
                        Tonometry.Lcolorprogress = (Tonometry.ColorLeftEyeValue >= 0 && Tonometry.ColorLeftEyeValue <= 4) ? "red" : ((Tonometry.ColorLeftEyeValue >= 10 && Tonometry.ColorLeftEyeValue <= 18) ? "" : ((Tonometry.ColorLeftEyeValue >= 19 && Tonometry.ColorLeftEyeValue <= 21) ? "#e6b800" : ((Tonometry.ColorLeftEyeValue >= 5 && Tonometry.ColorLeftEyeValue <= 9) ? "#e6b800" : ((Tonometry.ColorLeftEyeValue >= 22) ? "red" : "black"))));
                    }
                }
                Tonometry.DropGivenBy = Tonometry.DropGivenBy || 0;
                if (Tonometry.DropGivenBy !== 0) {
                    var Arraylist = $filter("filter")($scope.allUserList, function (kitem) { return kitem.DoctorID == Tonometry.DropGivenBy }, true);
                    if (Arraylist.length > 0) {
                        Tonometry.DropGivenByName = Arraylist[0].FullName;
                    }
                } else {
                    Tonometry.DropGivenByName = '';
                }

                Tonometry.DropMedicineId = Tonometry.DropMedicineId || 0;
                if (Tonometry.DropMedicineId !== 0) {
                    var Arraylist = $filter("filter")($scope.MedicationArrayList, function (kitem) { return kitem.MedicationId == Tonometry.DropMedicineId }, true);
                    if (Arraylist.length > 0) {
                        Tonometry.DropMedicineName = Arraylist[0].MedicationName;
                    }
                } else {
                    Tonometry.DropMedicineName = '';
                }
                $scope.VisionObj.TonoMetryDetailsArray.IOPArray = $scope.VisionObj.TonoMetryDetailsArray.IOPArray || [];
                $scope.VisionObj.TonoMetryDetailsArray.IOPArray.push(Tonometry);
            }
            var pchyfilter = $filter("filter")($scope.VisionObj.PachymetryArray.Pachymetry, { "ActiveInd": 'Y' }, true) || [];
            if (pchyfilter.length == 0) {
                $scope.PatientPachymetryDetails = $scope.PatientPachymetryDetails || [];
                if ($scope.PatientPachymetryDetails.length > 0) {

                    /*angular.forEach($scope.PatientPachymetryDetails, function (mitem) {*/
                    if ($scope.PatientPachymetryDetails[0].InvestigationId === $scope.VisionObj.PachymetryArray.InvestigationId) {
                        $scope.VisionObj.PachymetryArray.PatientFindingPachymetryId = 0;
                        $scope.VisionObj.PachymetryArray.InvestigationId = $scope.PatientPachymetryDetails[0].InvestigationId;
                        $scope.VisionObj.PachymetryArray.CategoryId = $scope.PatientPachymetryDetails[0].CategoryId;
                        $scope.VisionObj.PachymetryArray.CategoryDesc = $scope.PatientPachymetryDetails[0].CategoryDesc;
                        $scope.VisionObj.PachymetryArray.InvestigationDesc = $scope.PatientPachymetryDetails[0].InvestigationDesc;
                        /*$scope.VisionObj.PachymetryArray.SubCategoryChildId = $scope.PatientPachymetryDetails[0].SubCategoryChildId||"";*/
                        $scope.VisionObj.PachymetryArray.Pachymetry = angular.copy($scope.PatientPachymetryDetails[0].Pachymetry);
                        $scope.VisionObj.PachymetryArray.Remarks = $scope.PatientPachymetryDetails[0].Remarks || "";
                    }
                    /*});*/

                }
            }
            $scope.TonometryObj = GetTonometryObj();
            var filter = $filter("filter")($scope.TonometrySubList, { "InvestigationId": Tonometry.InvestigationId }, true);
            if (filter.length > 0) {
                $scope.ChangeTonoMetryType(filter[0]);
            } else {
                $scope.ChangeTonoMetryType($scope.TonometrySubList[0]);
            }

            IOPandPachymetryAvgValues();
            $scope.IOPODValues = GetIOPValues();
            $scope.IOPOSValues = GetIOPValues();
        }
