        /*Pachymetry start*/
        $scope.AddPachymetryobj = function (obj) {
            if ($scope.PachymetryObj.RightEye == '' && $scope.PachymetryObj.LeftEye == '' && $scope.VisionObj.PachymetryArray.Pachymetry.length <= 2) {
                alertify.error("Please Enter Value");
                return false;
            }
            var Object = angular.copy(obj);
            if ($scope.VisionObj.PachymetryArray != undefined) {
                var PAM = $filter("filter")($scope.VisionObj.PachymetryArray.Pachymetry, { "ActiveInd": 'Y' }, true) || [];
                if (PAM.length <= 2) {
                    $scope.VisionObj.PachymetryArray.Pachymetry.push(Object);
                    $scope.PachymetryObj = GetPachymetryObj();
                    $scope.VisionObj.PachymetryArray.Remarks = '';
                }
                //if ($scope.VisionObj.PachymetryArray.Pachymetry.length <= 2) {
                //    $scope.VisionObj.PachymetryArray.Pachymetry.unshift(Object);
                //    $scope.PachymetryObj = GetPachymetryObj();
                //}
                else {
                    alertify.error("you are reached the Maximum limit");
                    $scope.PachymetryObj.RightEye = "";
                    $scope.PachymetryObj.LeftEye = "";
                }
            }
            Object.PachyGivenBy = Object.PachyGivenBy || 0;
            if (Object.PachyGivenBy !== 0) {
                var Arraylist = $filter("filter")($scope.allUserList, function (kitem) { return kitem.DoctorID == Object.PachyGivenBy }, true);
                if (Arraylist.length > 0) {
                    Object.PachyGivenByName = Arraylist[0].FullName;
                }
            } else {
                Object.PachyGivenByName = '';
            }


            IOPandPachymetryAvgValues();
        };
        $scope.changePAMSelectedItem = function (item, Invitem, EyeType, valueType, arrayList) {
            angular.forEach(arrayList, function (aitem) {
                aitem.selected = false;
            });
            angular.forEach($scope.VisionObj.VisionDetails, function (pitem) {
                if (pitem.InvestigationId == 2155) {
                    if (EyeType == "OD") {
                        pitem.RightEye = item.Value;
                        item.selected = true;
                    }
                    else if (EyeType == "OS") {
                        pitem.LeftEye = item.Value;
                        item.selected = true;
                    }
                }
            });
        }

        $scope.RemovePachymetryItem = function (item, index) {
            if (item.PatientFindingPachymetryId != 0) {
                item.ActiveInd = "N";
            } else {
                if ($scope.VisionObj.PachymetryArray != undefined) {
                    if ($scope.VisionObj.PachymetryArray.Pachymetry.length > 0) {
                        var index = $scope.VisionObj.PachymetryArray.Pachymetry.indexOf(item);
                        if (item.PatientFindingPachymetryId === 0) {
                            if (index > -1) {
                                $scope.VisionObj.PachymetryArray.Pachymetry.splice(index, 1);
                            }
                        }
                    }
                }

            }

            IOPandPachymetryAvgValues();
        }
