        $scope.AddNewAutoRefractionObj = function (Obj, final) {

            if ($scope.VisionObj.AutoRefractionDetails.length > 0) {
                if ($scope.VisionObj.AutoRefractionDetails[0].AutoRefraction != undefined) {
                    var Arrayfilter = $filter("filter")($scope.VisionObj.AutoRefractionDetails[0].AutoRefraction, { "ActiveInd": "Y" }, true) || [];
                    if (Arrayfilter.length >= 4) {
                        if (final == "Final") { } else {
                            alertify.error("Maximum No. of times entered. ");
                        }
                        return false;
                    }
                }
            }

            if ($scope.AutorefraObj.RightEyeValues.Spherical == '' && $scope.AutorefraObj.RightEyeValues.Cylindrical == '' && $scope.AutorefraObj.RightEyeValues.Axis == '' &&
                $scope.AutorefraObj.LeftEyeValues.Spherical == '' && $scope.AutorefraObj.LeftEyeValues.Cylindrical == '' && $scope.AutorefraObj.LeftEyeValues.Axis == '' && $scope.AutorefraObj.Remarks == '') {

                alertify.error("Please Enter Any One Value");
                return false;
            }
            var Object = angular.copy(Obj);
            angular.forEach($scope.VisionObj.AutoRefractionDetails, function (aitem) {
                if (aitem.InvestigationId == 2113) {
                    Object.PatientFindingAutoRefractionId = 0;
                    Object.InvestigationId = aitem.InvestigationId;
                    Object.CategoryId = aitem.CategoryId;
                    Object.CategoryDesc = aitem.CategoryDesc;
                    Object.InvestigationDesc = aitem.InvestigationDesc;
                    aitem.AutoRefraction.push(Object);
                }
            });
            $scope.AutorefraObj = GetAutorefraObj();
            $scope.AutoSphericalPlusList = GetSphericalPlusList();
            $scope.AutoSphericalMinusList = GetSphericalMinusList();
            $scope.AutoCylindricalList = GetCylindricalList();
            $scope.AutoCylMinusList = GetCylMinusList();
            $scope.AutoAxisList = GetAxisList();
            $scope.VisionObj.AutoSelectedEye = "OD";
            $scope.VisionObj.AutoSphericalSwitch = 1;
            $scope.VisionObj.AutoCylindricalSwitch = 1;
        }

