        $scope.AddNewOverObj = function (Obj, final) {

            if ($scope.VisionObj.OverRefractionDetails.length > 0) {
                if ($scope.VisionObj.OverRefractionDetails[0].OverRefraction != undefined) {
                    var Arrayfilter = $filter("filter")($scope.VisionObj.OverRefractionDetails[0].OverRefraction, { "ActiveInd": "Y" }, true) || [];
                    if (Arrayfilter.length >= 4) {
                        if (final == "Final") { } else {
                            alertify.error("Maximum No. of times entered. ");
                        }
                        return false;
                    }
                }
            }
            if ($scope.OverRefractionObj.RCylindrical == '' && $scope.OverRefractionObj.RSpherical == '' && $scope.OverRefractionObj.RAxis == '' && $scope.OverRefractionObj.RAdition == '' && $scope.OverRefractionObj.RBCVA == '' && $scope.OverRefractionObj.RBCNVA == '' && $scope.OverRefractionObj.RVAI == '' &&
                $scope.OverRefractionObj.LCylindrical == '' && $scope.OverRefractionObj.LSpherical == '' && $scope.OverRefractionObj.LAxis == '' && $scope.OverRefractionObj.LAdition == '' && $scope.OverRefractionObj.LBCVA == '' && $scope.OverRefractionObj.LBCNVA == '' && $scope.OverRefractionObj.LVAI == '' &&
                $scope.OverRefractionObj.BBCVA == '' && $scope.OverRefractionObj.BBCNVA == '' && $scope.OverRefractionObj.BVAI == '' && $scope.OverRefractionObj.Remarks == '') {

                alertify.error("Please Enter Any One Value");
                return false;
            }

            var Object = angular.copy(Obj);
            angular.forEach($scope.VisionObj.OverRefractionDetails, function (aitem) {
                if (aitem.InvestigationId == 2116) {
                    Object.PatientFindingOverRefractionId = 0;
                    Object.InvestigationId = aitem.InvestigationId;
                    Object.CategoryId = aitem.CategoryId;
                    Object.CategoryDesc = aitem.CategoryDesc;
                    Object.InvestigationDesc = aitem.InvestigationDesc;
                    aitem.OverRefraction.push(Object);
                }
            });
            $scope.OverRefractionObj = GetOverRefractionObj();
            $scope.VisionObj.OverSelectedEye = "OD";
            $scope.VisionObj.OverSphericalSwitch = 1;
            $scope.VisionObj.OverCylindricalSwitch = 1;

            $scope.OverSphericalPlusList = angular.copy(GetSphericalPlusList());
            $scope.OverSphericalMinusList = angular.copy(GetSphericalMinusList());
            $scope.OverCylindricalPlusList = angular.copy(GetCylindricalList());
            $scope.OverCylMinusList = angular.copy(GetCylMinusList());
            $scope.OverAxisList = angular.copy(GetAxisList());
            $scope.OverAddtionList = angular.copy(GetAddtionList());
            $scope.OverBCVAList = angular.copy(GetRefBcvaList());
            $scope.OverBCNVAList = angular.copy(GetBcnvaList());
            $scope.OverVAIList = angular.copy(GetBcnvaList());
        }
