        function ParseFGRXDate(value) {
            if (!value) {
                return null;
            }
            if (angular.isDate(value)) {
                return isFinite(value.getTime()) ? value : null;
            }
            var text = String(value).trim();
            var mdy = /^(\d{1,2})-(\d{1,2})-(\d{4})$/.exec(text);
            if (mdy) {
                return new Date(+mdy[3], +mdy[1] - 1, +mdy[2]);
            }
            var parsed = new Date(text);
            return isFinite(parsed.getTime()) ? parsed : null;
        }
        $scope.ChangeExpirationYear = function (item) {
            item.ExpirationYearId = item.ExpirationYearId || "";
            if (item.ExpirationYearId == "") {
                item.ExpirationYearId = "";
                item.ExpirationYearName = "";
            } else {
                if (item.ExpirationYearId != 0) {
                    var filter = $filter("filter")($scope.GetExpirationyearList, { "Id": item.ExpirationYearId }, true) || [];
                    if (filter.length > 0) {
                        item.ExpirationYearName = filter[0].Name;
                    }
                }

                // Nimeshika told expiration date count from Appointment date (Divyasri)
                // var currentDate = new Date();

                var baseDate = ParseFGRXDate($scope.FGRXNewObj.FGRXAppointmentDate)
                    || ParseFGRXDate($scope.FGRXNewObj.ConsultationDt);

                if (!baseDate) {
                    return;
                }

                var AppointmentDate = new Date(baseDate.getFullYear(), baseDate.getMonth(), baseDate.getDate());
                AppointmentDate.setHours(12, 0, 0, 0);

                var duration = item.ExpirationYearName;

                if (duration.includes("months")) {
                    var months = parseInt(duration);
                    AppointmentDate.setMonth(AppointmentDate.getMonth() + months);
                } else if (duration.includes("year")) {
                    var years = parseInt(duration);
                    AppointmentDate.setFullYear(AppointmentDate.getFullYear() + years);
                }

                item.ExpirationDate = AppointmentDate;

                if (item === $scope.FGRXNewObj) {
                    $scope.FGRXNewObj.ExpirationDate = $filter("date")(item.ExpirationDate, "MM-dd-yyyy");
                }
            }
        };

