            let temparray = $filter("filter")($scope.VisionObj.GlassRxRefractionDetails[0].GlassRxRefraction, { "ActiveInd": 'Y' }, true)

            const overRefractionIndex = id - 1;
            const overRefractionData = $scope.VisionObj.OverRefractionDetails[0].OverRefraction[overRefractionIndex];

            const propertiesToCopy = [
                "RSpherical", "RCylindrical", "RAxis", "RAdition", "RBCVA", "RBCNVA",
                "RVAI", "RPrismVt", "RBaseVt", "RPrismHz", "RBaseHz", "LSpherical",
                "LCylindrical", "LAxis", "LAdition", "LBCVA", "LVAI", "LPrismVt",
                "LBaseVt", "LPrismHz", "LBaseHz", "Remarks", "Purpose", "PurposeId",
                "ExpirationYearName", "EnteredbyName", "EnteredbyId", "PrescribedbyId",
                "ExpirationYearId", "LBCNVA"
            ];

            for (const property of propertiesToCopy) {
                //  $scope.VisionObj.GlassRxRefractionDetails[0].GlassRxRefraction[fgxindex][property] = angular.copy(overRefractionData[property]) || "";

                temparray[fgxindex][property] = angular.copy(overRefractionData[property]) || "";
            }
            $scope.ManufestObj.ManifestID = "";
            $scope.CycloplegicObj.CycloplegicID = '';
