        $scope.CopyAutoRefraction = function (ITEM) {
            var cpyarray = [];
            cpyarray.push(ITEM);
            var rindex = $scope.SeletedRefractionIndicesObj.SelectedARIndex || 0;
            var currentARItem = $scope.VisionObj.AutoRefractionDetails[0].AutoRefraction[rindex];

            if (cpyarray.length != 0) {
                var nextIndex = rindex;
                if (currentARItem.IsDataAdded) {
                    nextIndex = rindex + 1;
                    while (nextIndex < $scope.VisionObj.AutoRefractionDetails[0].AutoRefraction.length &&
                        $scope.VisionObj.AutoRefractionDetails[0].AutoRefraction[nextIndex].IsDataAdded) {
                        nextIndex++;
                    }
                }
                if (nextIndex < $scope.VisionObj.AutoRefractionDetails[0].AutoRefraction.length) {
                    $scope.VisionObj.AutoRefractionDetails[0].AutoRefraction[nextIndex].RightEyeValues.Spherical = angular.copy(cpyarray[0].RSpherical) || "";
                    $scope.VisionObj.AutoRefractionDetails[0].AutoRefraction[nextIndex].RightEyeValues.Cylindrical = angular.copy(cpyarray[0].RCylindrical) || "";
                    $scope.VisionObj.AutoRefractionDetails[0].AutoRefraction[nextIndex].RightEyeValues.Axis = angular.copy(cpyarray[0].RAxis) || "";
                    $scope.VisionObj.AutoRefractionDetails[0].AutoRefraction[nextIndex].LeftEyeValues.Spherical = angular.copy(cpyarray[0].LSpherical) || "";
                    $scope.VisionObj.AutoRefractionDetails[0].AutoRefraction[nextIndex].LeftEyeValues.Cylindrical = angular.copy(cpyarray[0].LCylindrical) || "";
                    $scope.VisionObj.AutoRefractionDetails[0].AutoRefraction[nextIndex].LeftEyeValues.Axis = angular.copy(cpyarray[0].LAxis) || "";
                    $scope.VisionObj.AutoRefractionDetails[0].AutoRefraction[nextIndex].Remarks = angular.copy(cpyarray[0].Remarks);
                    ITEM.iscopied = true;
                    if ($scope.subtab !== 1) {
                        $scope.autosubChangeTab(1);
                    }
                } else {
                    alertify.error('Data Is Already Added For  AR1,AR2,AR3,AR4');
                }
            }

        }
