        function openNextDropdown(nextModel) {
            if (!nextModel || $scope.RorientationObj.RType === 'RGrid') return;
            $timeout(function () {
                $('.dropdown.open').removeClass('open');
                var $next = $('[ng-model="' + nextModel + '"]');
                if ($next.length) {
                    $next.closest('.dropdown').addClass('open');
                    $next.focus();
                }
            }, 300);
        }


