        $scope.DeleteRT = function (item) {
            var r = alertify.confirm("<b class='txt-centre'>Confirm !</b><h4 class='txt-body-centre'>Are you sure you want to delete this values?", function () {
                var index = $scope.VisionObj.RTDetails.indexOf(item);
                if (item.PatientFindingRetinoscopyRefractionId == 0) {
                    if (index > -1) {
                        $scope.VisionObj.RTDetails.splice(index, 1);
                    }
                } else {
                    item.DeleteInd = "Y";
                }

                if ($scope.VisionObj.RTDetails.length > 0) {
                    angular.forEach($scope.VisionObj.RTDetails, function (item, index) {
                        item.Sno = index + 1;
                    });
                }
                $scope.$digest();
            }, function () {
                r = "";
            });
        }

