        $scope.changeDistanceSign = function (eyeValues, field, dir) {

            var signField = field + "SignValue";
            var originalField = "Original" + field;

            if (!eyeValues[field])
                return;

            if (!eyeValues[originalField])
                eyeValues[originalField] = eyeValues[field];

            if (eyeValues[signField] == null)
                eyeValues[signField] = 0;

            eyeValues[signField] += dir;

            if (eyeValues[signField] > 4)
                eyeValues[signField] = 4;

            if (eyeValues[signField] < -4)
                eyeValues[signField] = -4;

            var original = eyeValues[originalField];

            if (eyeValues[signField] === 0)
                eyeValues[field] = original;
            else if (eyeValues[signField] > 0)
                eyeValues[field] = original + " +" + eyeValues[signField];
            else
                eyeValues[field] = original + " " + eyeValues[signField];
        };

        function VaBaseValue(ev, prop) {
            if (!ev) return '';
            if (ev[prop] === undefined || ev[prop] === null || ev[prop] === '') { return ''; }
            var base = ev['Original' + prop];
            if (base === undefined || base === null || base === '') {
                var raw = ev[prop];
                if (raw === undefined || raw === null) return '';
                var m = String(raw).match(/^(.*?)(?:\s*[+-]\d+)?$/);
                base = (m && m[1] !== undefined) ? m[1].trim() : String(raw);
            }
            return base;
        }
        $scope.VaBaseValue = VaBaseValue;

        $scope.vaSelectedEyeValues = function (vitem) {
            if (!vitem) return null;
            var eye = $scope.VisionObj.VisualSelectedEye;
            if (eye === 'OS') return vitem.LeftEyeValues;
            if (eye === 'OU') return vitem.BothEyeValues;
            return vitem.RightEyeValues;
        };

        $scope.vaHasValue = function (vitem, prop) {
            var ev = $scope.vaSelectedEyeValues(vitem);
            return !!(ev && ev[prop]);
        };

        $scope.vaSign = function (vitem, prop) {
            var ev = $scope.vaSelectedEyeValues(vitem);
            if (!ev) return 0;
            var v = ev[prop + 'SignValue'];
            return (v === undefined || v === null) ? 0 : v;
        };


        $scope.vaSetSign = function (vitem, prop, m) {
            var ev = $scope.vaSelectedEyeValues(vitem);
            if (!ev) return;
            $scope.changeDistanceSign(ev, prop, m - $scope.vaSign(vitem, prop));
        };

