        $scope.OpenVisualAcuityGraph = function () {

            var modalInstance = $uibModal.open({
                templateUrl: "visualacuityshowgraph.html",
                backdrop: "static",
                keyboard: false,
                scope: $scope,
                windowClass: "modal__popup--1 bottom-to-top-modal pt__180--",
                controller: function ($scope, $uibModalInstance) {

                    $scope.uibclose = function () {
                        $uibModalInstance.dismiss("cancel");
                    };

                }
            });

            modalInstance.rendered.then(function () {
                $scope.ShowVisualAcuityGraphnew();
            });

        };

        $scope.rGridEyeVal = function (baseProp) {
            var g = $scope.RGrid;
            if (!g || !g.obj || !g.field) return '';
            if (g.field.nested) {
                var bind = (g.eye === 'OS') ? 'LeftEye' : (g.eye === 'OU') ? 'BothEye' : 'RightEye';
                return (g.obj[bind] && g.obj[bind][baseProp]) || '';
            } else {
                var prefix = (g.eye === 'OS') ? 'L' : (g.eye === 'OU') ? 'B' : 'R';
                return g.obj[prefix + baseProp] || '';
            }
        };


