        $scope.SaveAmslerGriddata = function (type) {

            $scope.cacheStorageItem.NewAmslerGridArray = $scope.cacheStorageItem.NewAmslerGridArray || [];

            angular.forEach($scope.cacheStorageItem.NewAmslerGridArray, function (item) {
                if (item.InvestigationId != 2132) return;

                // map scope draw-lists onto the record (same as the working controller)
                item.RDrawList = $scope.AmslerGridODDrawList || [];
                item.LDrawList = $scope.AmslerGridOSDrawList || [];
                item.IsSummaryEdit = false;

                var odChecked = (item.RDrawList || []).some(function (c) { return c.IsChecked; });
                var osChecked = (item.LDrawList || []).some(function (c) { return c.IsChecked; });
                var hasFiles = (item.Files || []).some(function (f) { return f.DeleteInd === 'N'; });

                if (odChecked || osChecked || hasFiles ||
                    (item.RightEyeId && item.RightEyeId !== 0) ||
                    (item.LeftEyeId && item.LeftEyeId !== 0) ||
                    (item.RightEyeRemarks && item.RightEyeRemarks !== '') ||
                    (item.LeftEyeRemarks && item.LeftEyeRemarks !== '')) {
                    item.ActiveInd = 'Y';
                    item.IsInvDataAdded = true;
                } else {
                    item.IsInvDataAdded = false;
                }
            });

            $scope.FinalNewAmslerGridArray = [];
            $scope.FinalNewAmslerGridArray = $filter("filter")($scope.cacheStorageItem.NewAmslerGridArray, { "IsInvDataAdded": true }, true);
            var object = {
                "VisitId": $scope.cacheStorageItem.PatientVisitId,
                "UserId": $scope.UserId || 0,
                "AppointmentID": $scope.appointmentInfo.AppointmentID || 0,
                "AmslergridDetails": $scope.FinalNewAmslerGridArray || [],
            };

            eHnotePatientDataService.AddNewAmslergridDetails(object).then(function (resp) {
                if (resp.data.Status == "Success") {
                    if (type !== 'Autosave') {
                        alertify.success("Saved Successfully");
                        var obj = {
                            "VisionObj": $scope.VisionObj || "",
                            "cacheStorageItem": $scope.cacheStorageItem || ""
                        }
                        $scope.AfterSaveNavigate(object);
                    }
                } else {
                    alertify.error('save is failed');
                }
            }, function (err) {

            });
        }
