        $scope.GetOrgDilationMedication = function (HospitalID) {
            $scope.LabsearchText = "";
            eHnoteSettingsDataService.GetOrgDilationMedication($scope.LabsearchText, $scope.HospitalId).success(function (data) {
                $scope.DilationList = data || [];
                if ($scope.DilationList.length > 0) {
                    angular.forEach($scope.DilationList, function (item) {
                        item.DeleteInd = 'N';
                    });
                }
                var medobj = $filter("filter")($scope.DilationList, { "IsDefault": false }, true) || [];
                $scope.MedicationObj = medobj.length !== 0 ? medobj[0] : '';

                if ($scope.DilationEntryObj &&
                    (!$scope.DilationEntryObj.dilationList || $scope.DilationEntryObj.dilationList.length === 0)) {
                    $scope.DilationEntryObj.dilationList = angular.copy($scope.DilationList || []);
                }
            })
                .error(function (error) {
                    alertify.error("");
                });
        };

